// Initialize DB from localStorage or seed — auto-reset when SEED_VERSION changes
const VER_KEY='satui_proto_seed_ver';
if(localStorage.getItem(VER_KEY)!==SEED_VERSION){
  localStorage.removeItem(STORE_KEY);
  localStorage.setItem(VER_KEY,SEED_VERSION);
}
let DB = loadStore() || JSON.parse(JSON.stringify(SEED));
if(!loadStore()) saveStore();

// Helpers
function dbGet(table){return DB[table]||[]}
function dbFind(table,id){return (DB[table]||[]).find(r=>r.id===id)}
function dbAdd(table,row){DB[table].push(row);saveStore();return row}
function dbUpdate(table,id,patch){
  const i=(DB[table]||[]).findIndex(r=>r.id===id);if(i<0)return null;
  Object.assign(DB[table][i],patch);saveStore();return DB[table][i];
}
function dbRemove(table,id){DB[table]=(DB[table]||[]).filter(r=>r.id!==id);saveStore()}
function dbReset(){localStorage.removeItem(STORE_KEY);DB=JSON.parse(JSON.stringify(SEED));saveStore()}
function fmtRupiah(n){return 'Rp '+n.toLocaleString('id-ID')}
function fmtTime(iso){if(!iso)return'';const d=new Date(iso);return d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}
function fmtDate(iso){if(!iso)return'';const d=new Date(iso);return d.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})}
function genId(prefix){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,5)}

